import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Definizione di rette parallele","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/ff/ffb.md","filePath":"lezioni/f_geometria-del-piano-euclideo/ff/ffb.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/ff/ffb.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="definizione-di-rette-parallele" tabindex="-1">Definizione di rette parallele <a class="header-anchor" href="#definizione-di-rette-parallele" aria-label="Permalink to “Definizione di rette parallele”">​</a></h1><p class="text-blue">[Due rette si dicono parallele se non hanno nessun punto in comune]</p><blockquote><p><strong>Attento:</strong> perché nella sua apparente semplicità la definizione è piuttosto complicata: significa che le rette non si incontrano mai, cioè se io procedo per <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn></mrow><annotation encoding="application/x-tex">1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> chilometro ancora le rette non si incontrano, ma nemmeno dopo un milione di chilometri e anche dopo aver percorso tutto l&#39;universo ancora non si incontreranno (l&#39;universo e la geometria euclidea non vanno troppo d&#39;accordo).</p><p>Sorge il problema di come fare a verificare se effettivamente le rette non si incontrano: dovremo studiare un criterio (scorciatoia) per capire senza percorrere miliardi di miliardi di chilometri (e non basterebbe) se le rette sono parallele.</p></blockquote>`,3)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};